$sql = @'
USE master;
GO

PRINT '== Drop existing MI cert/login if any =='
IF EXISTS (SELECT 1 FROM sys.server_principals WHERE name = 'MIAGLogin')
    DROP LOGIN MIAGLogin;
GO
IF EXISTS (SELECT 1 FROM sys.certificates WHERE name = 'MICert')
    DROP CERTIFICATE MICert;
GO

PRINT '== Create MI cert from binary on SQL Server =='
CREATE CERTIFICATE MICert AUTHORIZATION dbo FROM BINARY = ;
GO

PRINT '== Create login from MI cert =='
CREATE LOGIN MIAGLogin FROM CERTIFICATE MICert;
GO

PRINT '== Grant CONNECT on endpoint to MI login =='
GRANT CONNECT ON ENDPOINT::Hadr_endpoint TO MIAGLogin;
GO

PRINT '== Verify =='
SELECT 'Cert' AS Section, name, thumbprint FROM sys.certificates WHERE name IN ('MILinkCert', 'MICert')
UNION ALL
SELECT 'Login', name, type_desc FROM sys.server_principals WHERE name = 'MIAGLogin';
GO
'@
$sql | Out-File "C:\MILink\import-mi-cert.sql" -Encoding ASCII
& sqlcmd -S . -E -b -i "C:\MILink\import-mi-cert.sql" 2>&1
Write-Output "Exit: $LASTEXITCODE"
